package org.example.behavioral_pattern.observer_pattern.spring_boot;import org.springframework.boot.CommandLineRunner;import org.springframework.boot.SpringApplication;import org.springframework.boot.autoconfigure.SpringBootApplication;@SpringBootApplicationpublic class ObserverSpringBootApp implements CommandLineRunner {    private final OrderService orderService;    public ObserverSpringBootApp(OrderService orderService) {        this.orderService = orderService;    }    public static void main(String[] args) {        SpringApplication.run(ObserverSpringBootApp.class, args);    }    @Override    public void run(String... args) {        orderService.createOrder("customer@example.com", 199.99);    }}